# ---------------------------------------------------------------------------------------------------------------------
# METRICS SERVER
# ---------------------------------------------------------------------------------------------------------------------
locals {
  datadog_agent_enabled = (
    var.datadog_agent_enabled != null
    ? var.datadog_agent_enabled
    : lookup(var.datadog_agent_enabled_cluster_types, local.cluster_type, true)
  )

  vector_dd_agent_logs_enabled = (
    var.vector_dd_agent_logs_enabled != null
    ? var.vector_dd_agent_logs_enabled
    : local.vector_enabled
  )
}

# Datadog Agent
module "datadog_agent" {
  source  = "crow.infrastructure.immuta.io/internal/monitoring-datadog-agent/kubernetes"
  version = "1.1.2"
  count  = local.datadog_agent_enabled ? 1 : 0

  providers = {
    kubernetes = kubernetes.local-cluster
    helm       = helm.local-cluster
  }

  chart_version                  = var.datadog_agent_version
  image_tag                      = var.datadog_agent_image_tag
  create_namespace               = var.datadog_create_namespace
  cluster_name                   = var.cluster_name
  global_segment                 = var.global_segment
  datadog_tags                   = var.datadog_tags
  enable_nowrds_monitoring       = var.datadog_enable_nowrds_monitoring
  enable_now_obfusicator_options = var.datadog_enable_now_obfusicator_options
  enable_mrds_monitoring         = var.datadog_enable_mrds_monitoring
  now_obfusicator_options        = var.datadog_now_obfusicator_options

  logs_intake_url                = local.vector_dd_agent_logs_enabled ? module.vector[0].service_endpoint_dd_agent : null

  tags                           = var.tags
  env                            = var.env
}

# ---------------------------------------------------------------------------------------------------------------------
# REQUIRED PARAMETERS
# These variables must be set.
# ---------------------------------------------------------------------------------------------------------------------
variable "datadog_agent_version" {
  description = "Version of otel-collector helm chart"
  type        = string
  default     = ""
  validation {
    condition     = var.datadog_agent_version == "" && local.datadog_agent_enabled ? false : true
    error_message = "datadog_agent_version must be set when datadog_agent is enabled"
  }
}

variable "datadog_agent_image_tag" {
  description = "Version of otel-collector image tag"
  type        = string
  default     = ""
  validation {
    condition     = var.datadog_agent_image_tag == "" && local.datadog_agent_enabled ? false : true
    error_message = "datadog_agent_image_tag must be set when datadog_agent is enabled"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL PARAMETERS
# These variables are configurable, but have reasonable defaults set.
# ---------------------------------------------------------------------------------------------------------------------
variable "datadog_agent_enabled_cluster_types" {
  description = "Types of clusters datadog_agent should be enabled on by default"
  type        = map(string)
  default = {
    "mgmt"  = true
    "cps"   = true
    "saas"  = true
    "infra" = false
    "dev"   = false
  }
}

variable "datadog_tags" {
  description = "Map of tags to apply to datadog metrics"
  type        = list(string)
  default     = []
}

variable "datadog_enable_nowrds_monitoring" {
  description = "Enable monitoring for NOWRDS."
  type        = bool
  default     = false
}

variable "datadog_enable_mrds_monitoring" {
  description = "Enable multitenant RDS monitoring"
  type        = bool
  default     = false
}

variable "datadog_enable_now_obfusicator_options" {
  description = "Whether to enable the NOWRDS obfuscator options in the Datadog agent configuration."
  type        = bool
  default     = false
}

variable "datadog_now_obfusicator_options" {
  description = "A map of options to configure the NOWRDS obfuscator in the Datadog agent configuration."
  type        = map(string)
  default = {
    replace_digits = "true"
  }
}

variable "datadog_create_namespace" {
  type    = bool
  default = false
}

variable "datadog_agent_enabled" {
  description = "Override for explicitly enabling or disabling otel-collector"
  type        = bool
  default     = null
}

variable "vector_dd_agent_logs_enabled" {
  description = "Override for routing DD Agent logs through Vector. When null (default), inherits from local.vector_enabled (i.e., on wherever Vector is on). Set to false to keep DD Agent shipping logs directly to DD SaaS even when Vector is deployed."
  type        = bool
  default     = null
}

# ---------------------------------------------------------------------------------------------------------------------
# VECTOR
# ---------------------------------------------------------------------------------------------------------------------
locals {
  vector_enabled = (
    var.vector_enabled != null
    ? var.vector_enabled
    : lookup(var.vector_enabled_cluster_types, local.cluster_type, true)
  )
}

module "vector" {
  source = "crow.infrastructure.immuta.io/internal/monitoring-vector/kubernetes"
  version = "1.1.0"

  count  = local.vector_enabled ? 1 : 0

  providers = {
    kubernetes = kubernetes.local-cluster
    helm       = helm.local-cluster
  }

  chart_version               = var.vector_chart_version
  image                       = var.vector_image
  image_tag_version           = var.vector_image_tag
  replicas                    = var.vector_replicas
  datadog_site                = var.vector_datadog_site
  datadog_api_key_vault_path  = var.vector_datadog_api_key_vault_path
  audit_drop_patterns         = var.vector_audit_drop_patterns
  email_redaction_enabled     = var.vector_email_redaction_enabled
  email_redaction_replacement = var.vector_email_redaction_replacement
  email_redaction_dry_run     = var.vector_email_redaction_dry_run
  additional_config           = var.vector_additional_config

  # NOTE: The external-secrets internal-module (v1.2.0) has an empty outputs.tf
  # and does not expose cluster_secret_store_name. Until that output is added
  # to the external-secrets module, the ClusterSecretStore name is passed
  # explicitly via var.vector_external_secrets_cluster_store_name.
  # TODO: replace with module.external_secrets[0].cluster_secret_store_name
  # once the external-secrets internal-module exposes that output.
  external_secrets_cluster_store_name = var.vector_external_secrets_cluster_store_name

  depends_on = [
    module.cilium,
    module.external_secrets,
  ]
}

data "external" "vector_validate" {
  count = local.vector_enabled && !local.external_secrets_enabled ? 1 : 0

  program = ["Error: vector can only be set if external-secrets is enabled as well"]
}

# ---------------------------------------------------------------------------------------------------------------------
# REQUIRED PARAMETERS
# These variables must be set.
# ---------------------------------------------------------------------------------------------------------------------
variable "vector_chart_version" {
  description = "Version of vector helm chart"
  type        = string
  default     = ""
  validation {
    condition     = var.vector_chart_version == "" && local.vector_enabled ? false : true
    error_message = "vector_chart_version must be set when vector is enabled"
  }
}

variable "vector_image_tag" {
  description = "Vector image tag"
  type        = string
  default     = ""
  validation {
    condition     = var.vector_image_tag == "" && local.vector_enabled ? false : true
    error_message = "vector_image_tag must be set when vector is enabled"
  }
}

variable "vector_datadog_site" {
  description = "Datadog site for vector sinks (e.g. datadoghq.com)"
  type        = string
  default     = "datadoghq.com"
  validation {
    condition     = var.vector_datadog_site == "" && local.vector_enabled ? false : true
    error_message = "vector_datadog_site must be set when vector is enabled"
  }
}

variable "vector_datadog_api_key_vault_path" {
  description = "Vault path for the Datadog API key (consumed by ExternalSecret in vector ns)"
  type        = string
  default     = "secret/data/saas/infrastructure/datadog-api-key"
  validation {
    condition     = var.vector_datadog_api_key_vault_path == "" && local.vector_enabled ? false : true
    error_message = "vector_datadog_api_key_vault_path must be set when vector is enabled"
  }
}

variable "vector_external_secrets_cluster_store_name" {
  description = "Name of the ClusterSecretStore to use for vector ExternalSecret resources. Pass the name created by the external-secrets module (typically 'vault-cluster-store'). Required when vector is enabled."
  type        = string
  default     = "vault"
  validation {
    condition     = var.vector_external_secrets_cluster_store_name == "" && local.vector_enabled ? false : true
    error_message = "vector_external_secrets_cluster_store_name must be set when vector is enabled"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL PARAMETERS
# These variables are configurable, but have reasonable defaults set.
# ---------------------------------------------------------------------------------------------------------------------
variable "vector_enabled_cluster_types" {
  description = "Types of clusters Vector should be enabled on by default"
  type        = map(string)
  default = {
    "mgmt"  = true
    "cps"   = true
    "saas"  = true
    "infra" = false
    "dev"   = false
  }
}

variable "vector_enabled" {
  description = "Override for explicitly enabling or disabling Vector"
  type        = bool
  default     = null
}

variable "vector_image" {
  description = "Image for Vector"
  type        = string
  default     = "registry.ic-ops.net/cache-docker-hub/timberio/vector"
}

variable "vector_replicas" {
  description = "Number of Vector aggregator replicas"
  type        = number
  default     = 3
}

variable "vector_audit_drop_patterns" {
  description = "Regex patterns; matching log message bodies are dropped"
  type        = list(string)
  default = [
    "Audit\\s-\\s.+",
    "\"level\":\"audit\"",
  ]
}

variable "vector_email_redaction_enabled" {
  description = "Toggle the email-redact VRL transform across all signals"
  type        = bool
  default     = true
}

variable "vector_email_redaction_replacement" {
  description = "String that replaces matched email addresses"
  type        = string
  default     = "[REDACTED-EMAIL]"
}

variable "vector_email_redaction_dry_run" {
  description = "String to enable dry run on email redaction"
  type = bool
  default = false
}

variable "vector_additional_config" {
  description = "Alternate helm chart customConfig (overwrites entire helm config)"
  type        = any
  default     = null
}

